MAP
  NAME "EAR_100M"
  STATUS ON
  SIZE 800 600
  EXTENT 123 32 132 44
  UNITS DD
  IMAGETYPE "png"
  PROJECTION "init=epsg:4326" END
  SYMBOL
    NAME "circle"
    TYPE ELLIPSE
    POINTS 1 1 END
    FILLED TRUE
  END
  OUTPUTFORMAT
    NAME "png"
    DRIVER "AGG/PNG"
    MIMETYPE "image/png"
    IMAGEMODE RGBA
    TRANSPARENT ON
  END
  OUTPUTFORMAT
    NAME "geojson"
    DRIVER "OGR/GEOJSON"
    MIMETYPE "application/json"
    FORMATOPTION "STORAGE=stream"
    FORMATOPTION "FORM=SIMPLE"
  END
  WEB
    METADATA
      "ows_title" "EAR_100M layer services"
      "ows_enable_request" "GetCapabilities GetMap GetFeatureInfo DescribeFeatureType GetFeature"
      "ows_srs" "EPSG:4326 EPSG:3857"
      "wfs_namespace_prefix" "ear"
      "wfs_namespace_uri" "http://local-demo/ear100"
      "wfs_getfeature_formatlist" "geojson"
      "wms_getfeatureinfo_formatlist" "application/json"
      "ows_onlineresource" "http://127.0.0.1/cgi-bin/mapserv.exe?map=/ms4w/apps/local-demo/ear100-services.map&"
    END
  END
  LAYER
    NAME "AAL020"
    TYPE POLYGON
    STATUS ON
    DATA "D:/map/shp/EAR_100M/AAL020.shp"
    ENCODING "CP949"
    PROJECTION "init=epsg:4326" END
    TEMPLATE "queryable"
    TOLERANCE 7
    TOLERANCEUNITS PIXELS
    METADATA
      "ows_title" "AAL020"
      "gml_include_items" "all"
      "gml_types" "auto"
      "gml_featureid" "UID"
    END
    CLASS
      NAME "AAL020"
      STYLE COLOR 45 110 160 OPACITY 40 OUTLINECOLOR 70 110 130 END
    END
  END
